// readWindow(level, x, y, width, height) reads a window of a pyramid level, where level n is 2^n
// times coarser and x, y, width, height are in that level's pixels. Sources build their levels from
// overviews, JPEG 2000 resolution levels or strided reads.
export function pyramidSource(levels) {
  return { levels: levels.length, readWindow: (level, x, y, w, h) => levels[level].read(x, y, w, h) };
}

