// A decimated window: every step-th pixel of a region.
export async function decimatedWindow(source, x, y, width, height, step) {
  const full = await source.readWindow(0, x, y, width, height);
  const w = Math.ceil(width / step);
  const h = Math.ceil(height / step);
  const out = new full.constructor(w * h);
  for (let j = 0; j < h; j += 1) {
    for (let i = 0; i < w; i += 1) out[j * w + i] = full[j * step * width + i * step];
  }
  return { width: w, height: h, data: out };
}
